import {chapelQuest,CHAPEL_OBJECTIVES} from './chapel-quest.js';
import {addItem,countItem} from './inventory.js';
export const STORY_OBJECTIVES={...CHAPEL_OBJECTIVES,ritual_done:'Войдите в склеп и победите Лича',lich_relic:'Осмотрите останки Лича',lich_return:'Покажите медальон Джону',grave_search:'Найдите именную могилу за склепом на кладбище',grave_return:'Расскажите Джону о пустой могиле',chapter_complete:CHAPEL_OBJECTIVES.chapter_complete};
export const cryptUnlocked=p=>p.rewards.includes('ritual-purified');
export function chapterStory({p,slots,dungeon,cemetery,chapel,show,close,sync,sound,reward}){
 const next=chapelQuest({p,world:chapel,show,close,sync,sound,reward});
 function tick(){next.tick();if(p.stage==='ritual_done'&&dungeon?.boss?.hp===0){p.stage='lich_relic';sync();show('Последние слова Лича','«Ты снова пришёл… В прошлый раз ты сам просил меня забыть тебя. Эйрен… вспомни, почему».\nПод рассыпающейся короной остаётся медальон. Имя кажется чужим, но ты узнаёшь его прежде, чем успеваешь испугаться.')}}
 function claim(){if(p.stage!=='lich_relic')return;if(!countItem(slots,'memory_medallion')&&!addItem(slots,'memory_medallion'))return show('Медальон','Освободите ячейку в сумке. Медальон останется среди останков Лича.');p.stage='lich_return';reward(p,'lich-quest','quest',100);sync();sound();show('Чужое имя','В медальоне — твой портрет и портрет незнакомой женщины. На обороте: «Эйрен. Помни, ради кого». Джон может знать, откуда взялась эта вещь.')}
 function talk(){if(next.talk())return true;if(p.stage==='lich_return'){p.stage='grave_search';sync();sound();show('Джон','Этот медальон принадлежал Эйрену. Я сам высек его имя на камне много лет назад. Нет… не спрашивай, кого мы тогда похоронили.\nЗа склепом, в конце центральной дорожки, стоит могила с зеленоватым свечением. Осмотри её. Ведьма собирала память для Лича — но твою память кто-то отдал добровольно.');return true}if(p.stage==='grave_return'){p.stage='chapter_complete';reward(p,'empty-grave','quest',40);sync();sound();show('Джон','Значит, могила пуста. Я боялся, что так и будет. Ведьма была сборщицей, Лич — хранителем. Но никто из них не заставлял тебя забывать.\nТы сам просил спрятать своё прошлое. Что-то в нём удерживает древнюю печать. Я испытал твою тень, чтобы убедиться: ты сможешь вспомнить и не стать одним из мёртвых.\nОтветы остались у затопленной часовни. Если услышишь её колокол — не отвечай голосу женщины. Даже если узнаешь его.\nГлава 1 завершена. Если готов — поговори со мной ещё раз, и я покажу путь к часовне.');return true}if(Object.hasOwn(STORY_OBJECTIVES,p.stage)){show('Джон',p.stage==='grave_search'?'Ищи светящийся камень за склепом, в конце центральной дорожки.':p.stage==='chapter_complete'?'Когда откроется путь к часовне, тебе придётся решить: вернуть свою память или оставить печать нетронутой. Пока набирайся сил.':p.stage==='lich_relic'?'Не оставляй среди останков Лича то, что принадлежало тебе.':'Моя печать пропустит тебя в склеп. Найди того, кто собирает воспоминания.');return true}return false}
 function grave(){if(p.stage!=='grave_search')return;p.stage='grave_return';sync();show('Пустая могила','На камне высечено: «Эйрен. Пусть забытое останется под землёй».\nПод сдвинутой плитой нет останков. На внутренней стороне крышки процарапано: «Я выбрал забыть. Не дай мне вспомнить её голос».\nТы узнаёшь собственный почерк. Вернись к Джону.')}
 function prompt(){if(dungeon?.mode==='lich'&&p.stage==='lich_relic'&&dungeon.nearRemains?.())return 'E — Осмотреть останки Лича';if(cemetery?.nearStoryGrave?.()&&p.stage==='grave_search')return 'E — Осмотреть именную могилу';return ''}
 return {tick,claim,talk,grave,prompt,chapelInteract:next.interact};
}
